<?php
$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT t.*,c.full_name customer_name,c.phone customer_phone,u.name cashier_name FROM transactions t LEFT JOIN customers c ON c.id=t.customer_id LEFT JOIN users u ON u.id=t.cashier_id WHERE t.id=?');$q->execute([$id]);$tx=$q->fetch();if(!$tx){echo '<div class="alert alert-warning">Receipt not found.</div>';return;}
$q=db()->prepare('SELECT ti.*,s.name service_name,th.full_name therapist_name FROM transaction_items ti LEFT JOIN services s ON s.id=ti.service_id LEFT JOIN therapists th ON th.id=ti.therapist_id WHERE ti.transaction_id=?');$q->execute([$id]);$items=$q->fetchAll();
?>
<div class="page-heading no-print"><div><div class="eyebrow">Payment receipt</div><h1>Receipt</h1><p><?=h($tx['transaction_code'])?> · <?=date('F j, Y g:i A',strtotime($tx['created_at']))?></p></div><div class="d-flex gap-2"><a href="<?=h(app_page_url('transactions'))?>" class="btn btn-outline-secondary">Back</a><button class="btn btn-primary" onclick="window.print()"><i class="bi bi-printer me-1"></i>Print receipt / Save PDF</button></div></div>
<div class="receipt-paper"><div class="text-center mb-4"><?php if(setting('business_logo')):?><div class="mb-2"><img src="<?=h(app_url(setting('business_logo')))?>" alt="Business logo" style="max-width:130px;max-height:75px;object-fit:contain"></div><?php else:?><div class="brand-mark mx-auto mb-2"><i class="bi bi-flower1"></i></div><?php endif;?><h2 class="h4 mb-1"><?=h(setting('business_name','MAKAHUPAY REFLEX & MASSAGE'))?></h2><?php if(setting('business_address')):?><div class="small text-muted"><?=nl2br(h(setting('business_address')))?></div><?php endif;?><?php if(setting('contact_number')):?><div class="small text-muted"><?=h(setting('contact_number'))?></div><?php endif;?><div class="small text-muted mt-2">OFFICIAL PAYMENT RECEIPT</div></div><div class="receipt-line"><span>Transaction No.</span><strong><?=h($tx['transaction_code'])?></strong></div><div class="receipt-line"><span>Date</span><strong><?=date('F j, Y g:i A',strtotime($tx['created_at']))?></strong></div><div class="receipt-line"><span>Customer</span><strong><?=h($tx['customer_name']??'Guest / Walk-in')?></strong></div><?php if($tx['customer_phone']):?><div class="receipt-line"><span>Contact</span><strong><?=h($tx['customer_phone'])?></strong></div><?php endif;?><div class="my-3"><strong class="small text-uppercase text-muted">Items</strong><?php foreach($items as $it):?><div class="receipt-line"><div><strong><?=h($it['description'])?></strong><div class="small text-muted"><?=h($it['quantity'])?> × <?=money($it['unit_price'])?><?php if($it['therapist_name']):?> · Therapist: <?=h($it['therapist_name'])?><?php endif;?></div></div><strong><?=money($it['line_total'])?></strong></div><?php endforeach;?></div><div class="receipt-line"><span>Subtotal</span><strong><?=money($tx['subtotal'])?></strong></div><div class="receipt-line"><span>Discount</span><strong>− <?=money($tx['discount'])?></strong></div><div class="receipt-line fs-5"><strong>Total</strong><strong><?=money($tx['total'])?></strong></div><div class="receipt-line"><span>Payment method</span><strong><?=h(strtoupper(str_replace('_',' ',$tx['payment_method'])))?></strong></div><div class="receipt-line"><span>Amount received</span><strong><?=money($tx['amount_received'])?></strong></div><div class="receipt-line"><span>Change</span><strong><?=money($tx['change_amount'])?></strong></div><div class="receipt-line"><span>Cashier</span><strong><?=h($tx['cashier_name']??'—')?></strong></div><div class="text-center mt-4"><div class="fw-semibold"><?=h(setting('receipt_footer','Thank you for choosing Makahupay!'))?></div><div class="small text-muted mt-2">Please keep this receipt for your records.</div></div></div>
